	["The {quest:93341}"] = "{quest:93341}",
	-- {npc:254674} Woodwyrd · {area:2100} Maraudon
	-- plural, as words: Rowdy Roses = {npc:254566} Rowdy Rose · Terrible Tulips = {npc:254567} Terrible Tulip · Malevolent Marigolds = {npc:254572} Malevolent Marigold · Nascent Pylon Protectors = {npc:276401} Nascent Pylon Protector
	["Rowdy Roses and Terrible Tulips grow all over the gardens; the Malevolent Marigolds keep to the northern part. {npc:254674}, the treant in the middle of the gardens, has a request of his own that needs water from {area:2100}, a dungeon: this guide leaves it.\nThe Shen'dralar who wander the gardens are neutral, like the temple's guards: leave them be and pull the flowers away from them. Careful: Nascent Pylon Protectors (elites, 43) wander the zone's middle, the gardens too: keep clear of them."] = "정원 곳곳에 난폭한 장미와 끔찍한 튤립이 자라고, 악의에 찬 금잔화는 북쪽에 모여 있습니다. 정원 한가운데 있는 나무정령 {npc:254674}도 따로 부탁을 하는데, 던전인 {area:2100}의 물이 필요하므로 이 가이드에서는 다루지 않습니다.\n정원을 돌아다니는 셴드랄라는 사원 경비병처럼 중립이니 건드리지 말고 꽃들을 그들에게서 떨어진 곳으로 끌어오십시오. 주의: 갓 깨어난 수정탑 수호자(정예, 43)가 지역 중앙과 정원을 돌아다니니 멀리하십시오.",

	-- Step 25: Mithera
	-- {npc:255486} Historian Biraxas · {npc:254656} Magister Kirandis · {npc:252711} Decrepit Pylon Protector
	["{npc:255486}, inside the temple, has a task for you now that you have met {npc:254656}: the heart of a {npc:252711} (42-43, not elite), a short ride back up the road north."] = "{npc:254656}을(를) 만났으니 사원 안의 {npc:255486}이(가) 할 일을 줍니다. 길을 따라 북쪽으로 조금 돌아가면 있는 {npc:252711}(42-43, 비정예)의 심장입니다.",

	-- Step 26: A Heart of Crystal
	-- {npc:253471} Mordent Evenshade
	-- plural, as words: Decrepit Pylon Protectors = {npc:252711} Decrepit Pylon Protector
	["The nearest Decrepit Pylon Protectors stand by the road north, from the middle of the zone up to the western pylon, and around {npc:253471}'s overlook: one of them carries the heart Biraxas wants."] = "가장 가까운 노쇠한 수정탑 수호자는 지역 중앙에서 서쪽 수정탑까지 북쪽 길가와 {npc:253471}의 전망대 주변에 서 있습니다. 그중 하나가 비락사스가 원하는 심장을 지니고 있습니다.",

	-- Step 27: Historian Biraxas
	-- {zone:2652} Shen'dralas · {area:2657} Valley of Bones
	["{zone:2652} is done: ride back north through the {area:2657}; the next step says where your route goes on from there."] = "{zone:2652} 완료: {area:2657}을(를) 지나 다시 북쪽으로 가십시오. 그 다음 경로는 다음 단계에서 안내합니다.",

	-- Step 28: Shadowprey Village
	-- {zone:2652} Shen'dralas · {area:2657} Valley of Bones · {area:405} Desolace · {area:2408} Shadowprey Village · {area:1637} Orgrimmar · {zone:1444} Feralas · {area:1099} Camp Mojache
	["{zone:2652} is done. Ride back north through the {area:2657} and west along {area:405}'s southern edge to {area:2408}: the next guide picks up in {area:1637}, with the {zone:1444} guide's hand-ins. Your hearthstone is bound at {area:1099}: if it is ready, hearth there and fly to {area:1637} from {area:1099} instead."] = "{zone:2652} 완료. {area:2657}을(를) 지나 다시 북쪽으로, {area:405}의 남쪽 가장자리를 따라 서쪽 {area:2408}(으)로 가십시오. 다음 가이드는 {zone:1444} 가이드의 제출 퀘스트와 함께 {area:1637}에서 이어집니다. 귀환석이 {area:1099}에 설정되어 있으니, 사용할 수 있다면 대신 귀환석으로 그곳에 가서 {area:1099}에서 {area:1637}(으)로 날아가십시오.",
	-- {area:2408} Shadowprey Village
	["{area:2408} flight master"] = "{area:2408} 비행 조련사",

	-- Step 29: Back to your route
	["Back to your route"] = "원래 경로로 돌아가기",
	-- {zone:2652} Shen'dralas · {zone:1444} Feralas · {area:2657} Valley of Bones · {area:405} Desolace · {area:1108} Forgotten Coast · {area:1116} Feathermoon Stronghold
	["{zone:2652} is done. Your {zone:1444} guide picks up from here: ride back north through the {area:2657}, west along {area:405}'s southern edge and south into {zone:1444}, to the dock on the {area:1108} where the boat crosses to {area:1116}."] = "{zone:2652} 완료. 여기서부터 {zone:1444} 가이드가 이어집니다. {area:2657}을(를) 지나 다시 북쪽으로, {area:405}의 남쪽 가장자리를 따라 서쪽으로 간 뒤 남쪽 {zone:1444}(으)로 들어가, {area:1116}(으)로 가는 배가 출발하는 {area:1108}의 부두로 가십시오.",
}
